const __kcnt=(rp,S0,seat)=>{const one=x=>String(x==null?'':x).replace(/\\"/g,'"').replace(/[*_`]+/g,'').replace(/\s+/g,' ').trim();const VR=/\b((?:[1-3] )?(?:Song of Solomon|[A-Z][a-z]+)) (\d+):(\d+)\b/g;const __B=typeof REFP!=='undefined'&&REFP.BOOKS||[];const BK=new Set(Array.isArray(__B)?__B:String(__B).split('|'));const V=x=>{for(const m of String(x).matchAll(VR)){if(!BK.size||BK.has(m[1]))return m[1]+' '+m[2]+':'+m[3];}return null;};const VS=x=>[...new Set([...String(x).matchAll(VR)].filter(m=>!BK.size||BK.has(m[1])).map(m=>m[1]+' '+m[2]+':'+m[3]))];
 const kind=l=>{l=one(l).replace(/^(?:[-•]\s*)?/,'');let m=l.match(/^ANSWER CHECK\s*:\s*(.+?)\s+(?:--|—|–)\s/i);if(m){const g=(l.match(/(?:--|—|–)\s*(MEETS|MISSES|FAILS)\b/)||[])[1]||'';return {k:'AC',v:V(m[1]),bad:/^(?:MISSES|FAILS)$/.test(g),g};}m=l.match(/^(D\d+)\s+vs\.?\s+(C\d+)\s*\(([^)]*)\)\s*:\s*([A-Z][A-Z -]*[A-Z])/i);if(m)return {k:'CL',v:V(m[3]),pair:(m[1]+' vs '+m[2]).toUpperCase(),bad:/BROKEN/i.test(m[4]),g:m[4].trim()};return null;};
 const moved=new Map();for(const [o0,n0,id0] of (rp||[])){const ns=String(n0==null?'':n0).split('\n').map(kind).filter(Boolean);for(const o of String(o0==null?'':o0).split('\n').map(kind).filter(Boolean)){if(!o.bad||!o.v)continue;const n=ns.find(z=>z.k===o.k&&z.v===o.v&&(o.k!=='CL'||z.pair===o.pair));if(n&&!n.bad&&!moved.has(o.v))moved.set(o.v,{id:id0||'change',orig:one(o0),now:(o.k==='AC'?'ANSWER CHECK '+o.v+' now '+n.g:o.pair+' ('+o.v+') now '+n.g)});}}
 if(!moved.size)return '';const L=String(S0||'').replace(/\\n/g,'\n').replace(/\\"/g,'"').split('\n').map(one).filter(l=>l&&!/^\[AUDIT\b/.test(l));
 const still=new Set(L.map(kind).filter(z=>z&&z.bad&&z.v).map(z=>z.v));const out=[];
 for(let i=0;i<L.length;i++){const m=L[i].replace(/^(?:[-•]\s*)?/,'').match(/^RULING\s*(?:--|—|–|:)\s*(.*)$/i);if(!m)continue;const sg=m[1].split(/\s+(?:--|—|–)\s+/);const tg=(sg[0]||'').trim(),gr=(sg.length>1?sg[sg.length-1]:'').trim();if(!/^(?:(?:DEFENDER|CHALLENGER)\s+)?premise\s+\d+\b/i.test(tg)||!/^UNEXHIBITED\b/i.test(gr))continue;let nb='';for(let k=i+1;k<L.length&&k<=i+8;k++){if(/^(?:[-•]\s*)?RULING\s*(?:--|—|–|:)/i.test(L[k]))break;const f=L[k].replace(/^(?:[-•]\s*)?/,'').match(/^NAMED BY\s*:\s*(.*)$/i);if(f){nb=f[1];break;}}
  const vs=VS(nb);if(!vs.length||!vs.every(v=>moved.has(v)&&!still.has(v)))continue;const mv=moved.get(vs[0]);const cs=x=>(typeof cureSafe==='function'?cureSafe(x):String(x)).replace(/;/g,',');
  out.push('\n[AUDIT v39: K-RECHK -- '+(seat?'SEAT: '+seat+'; ':'')+'CHANGE: '+String(mv.id).replace(/;/g,',')+'; RULE: K-CNT; NEW: '+cs(tg)+' is still counted UNEXHIBITED, but its NAMED BY line names only '+vs.join(', ')+', and this change moved that grade ('+cs(mv.now)+'); the count is not re-derived (pkgACT, ASK 274); LINE: '+cs('RULING -- '+tg+' -- '+gr+' | NAMED BY: '+nb).slice(0,300)+'; ORIGINAL: '+cs(mv.orig).slice(0,300)+'; TRIAL rule, record-only ; END]');}
 return out.join('');};
